// intent: Verify that small null arrays are written in optimized form by to_ubjson.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = nlohmann::json::array({nullptr, nullptr, nullptr});
        std::vector<std::uint8_t> packed = nlohmann::json::to_ubjson(j);
        std::cout << "PACKED SIZE: " << packed.size() << std::endl;
        bool has_optimized = false;
        for (size_t i = 0; i < packed.size(); ++i) {
            if (packed[i] == '$') {
                has_optimized = true;
                break;
            }
        }
        std::cout << "HAS OPTIMIZED: " << std::boolalpha << has_optimized << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    }
    return 0;
}
